    BOOL bFileExists = D2Common::DATATBLS::DataTbls::CheckIfFileExists(nullptr, "Data\\Local\\Color.txt", &pFileHandle, 1);
    if (!bFileExists) {
      return;
    }

    D2FILE_ReadFile(nullptr, pFileHandle, &byColorByte, 1);
