    D2CharPortraitTextStrc* pDstChar = &sText;
    do {
      pSrcChar = pDstChar->szName;
      pDstChar = (D2CharPortraitTextStrc*)(pDstChar->szName + 1);
    } while (*pSrcChar != '\0');

    nHardcoreFlag = (int)pDstChar - (uintptr_t)&sText;
