// Client network timeout checks; triggers CLIENT_ConnectionRefused on long waits or failed connects.
void __stdcall Client_CheckConnectionTimeouts() {
    if (!(eD2GSGameType_007a0610 != GAMETYPE_SINGLEPLAYER && eD2GSGameType_007a0610 != GAMETYPE_SINGLEPLAYER_UNCAPPED)) {
      return;
    }

    DWORD nowTick = GetTickCount();
    int32_t connectOk = D2Net::SRC::Client::NET_CLIENT_GetConnectionTimeout();
    if (!connectOk && !D2CLIENT_ExitVar3 && ServerLoadingComplete) {
      CLIENT_ConnectionRefused(7);
    }
    if (gLevelLoadInProgress && nowTick - gConnectLongTimeoutStartTick > 300000) {
      CLIENT_ConnectionRefused(7);
    }
    if (nowTick - gConnectShortTimeoutStartTick > 30000 && !ServerLoadingComplete && !D2CLIENT_ExitVar3 && !gLevelLoadInProgress) {
      CLIENT_ConnectionRefused(6);
    }
    if (!(!D2GS_Connected && !ServerLoadingComplete && !D2CLIENT_ExitVar3 && !gLevelLoadInProgress && (eD2GSGameType_007a0610 == GAMETYPE_LAN_JOIN || eD2GSGameType_007a0610 == GAMETYPE_OBNET_JOIN))) {
      return;
    }

    CLIENT_ConnectionRefused(6);
}

// Main game loop tick. Runs at ~25 FPS.
// SP: Server tick (QSERVER_TickAllGames) + ClientSideGameLoop + render
// MP: Receive packets + ClientSideGameLoop + render
// Frame skip logic prevents runaway when overloaded. Exits when D2CLIENT_ExitVar3 set.
